// ---------------------------------------------------------------------------
// TestCaseCacheLambda - same VfsFixture pattern used by other test files
// ---------------------------------------------------------------------------
class TestCaseCacheLambda : public TestCaseBase<bool>
{
public:
    using Func = std::function<bool( VfsFixture & )>;

private:
    Func func;

public:
    TestCaseCacheLambda( const std::string & name_, Func func_,
                         bool expected_result_ = true )
    : TestCaseBase<bool>( name_, expected_result_ ),
      func( func_ )
    {}

    bool run() override
    {
        VfsFixture fix( name );
        return func( fix );
    }
};

// ---------------------------------------------------------------------------
// Helper: write a small file to drive b
// ---------------------------------------------------------------------------
static bool write_file( SimpleFlashFs::Vfs::VfsServerInterface & vfs,
                        const std::string & path,
                        const std::string & content )
{
    auto fh = vfs.open( path, std::ios::out | std::ios::trunc );
    if( !fh ) {
        CPPDEBUG( Tools::format( "write_file: cannot create %s", path ) );
        return false;
    }
    const auto * data = reinterpret_cast<const std::byte *>( content.data() );
    fh->write( data, content.size() );
    return fh->flush();
}

