std::shared_ptr<TestCaseBase<bool>> test_case_cache_static_nonexistent()
{
    return std::make_shared<TestCaseCacheLambda>( __FUNCTION__,
        []( VfsFixture & fix ) -> bool {
            if( !fix.run( "format a: ; format b: ;" ).all_ok ) {
                CPPDEBUG( "test_case_cache_static_nonexistent: format failed" );
                return false;
            }

            // Install static cache on drive b
            fix.drive_b->set_name_cache( std::make_unique<FramFsFileNameCacheStatic>() );

            if( !fix.drive_b->get_name_cache() || !fix.drive_b->get_name_cache()->is_valid() ) {
                CPPDEBUG( "test_case_cache_static_nonexistent: cache not valid after install" );
                return false;
            }

            // Try to open 100 non-existent files - all must return nullptr
            for( unsigned n = 1; n <= 100; ++n ) {
                const std::string path = Tools::format( "/b/measurements/%04u.ini", n );
                auto fh = fix.vfs->open( path, std::ios::in );
                if( fh ) {
                    CPPDEBUG( Tools::format( "test_case_cache_static_nonexistent: unexpectedly opened %s", path ) );
                    return false;
                }
            }

            // Cache must still report these names as absent
            for( unsigned n = 1; n <= 100; ++n ) {
                const std::string name = Tools::format( "measurements/%04u.ini", n );
                if( fix.drive_b->get_name_cache()->might_exist( name ) ) {
                    CPPDEBUG( Tools::format( "test_case_cache_static_nonexistent: might_exist returned true for absent '%s'", name ) );
                    return false;
                }
            }

            return true;
        } );
}
