std::shared_ptr<TestCaseBase<bool>> test_case_cache_write_then_read()
{
    return std::make_shared<TestCaseCacheLambda>( __FUNCTION__,
        []( VfsFixture & fix ) -> bool {
            if( !fix.run( "format a: ; format b: ;" ).all_ok ) {
                CPPDEBUG( "test_case_cache_write_then_read: format failed" );
                return false;
            }

            fix.drive_b->set_name_cache( std::make_unique<FramFsFileNameCacheDynamic>() );

            // Before write: file should not be in cache
            if( fix.drive_b->get_name_cache()->might_exist( "data/hello.txt" ) ) {
                CPPDEBUG( "test_case_cache_write_then_read: file unexpectedly pre-cached" );
                return false;
            }

            // Write the file
            if( !write_file( *fix.vfs, "/b/data/hello.txt", "hello cache" ) ) {
                CPPDEBUG( "test_case_cache_write_then_read: write failed" );
                return false;
            }

            // Cache should now report the file as potentially present
            if( !fix.drive_b->get_name_cache()->might_exist( "data/hello.txt" ) ) {
                CPPDEBUG( "test_case_cache_write_then_read: might_exist false after write" );
                return false;
            }

            // Read back: must succeed
            auto fh = fix.vfs->open( "/b/data/hello.txt", std::ios::in );
            if( !fh ) {
                CPPDEBUG( "test_case_cache_write_then_read: cannot re-open written file" );
                return false;
            }

            std::string buf( 11, '\0' );
            fh->read( reinterpret_cast<std::byte *>( buf.data() ), 11 );
            if( buf != "hello cache" ) {
                CPPDEBUG( Tools::format( "test_case_cache_write_then_read: content mismatch '%s'", buf ) );
                return false;
            }

            return true;
        } );
}
