std::shared_ptr<TestCaseBase<bool>> test_case_cache_invalidate_fallthrough()
{
    return std::make_shared<TestCaseCacheLambda>( __FUNCTION__,
        []( VfsFixture & fix ) -> bool {
            if( !fix.run( "format a: ; format b: ;" ).all_ok ) {
                CPPDEBUG( "test_case_cache_invalidate_fallthrough: format failed" );
                return false;
            }

            fix.drive_b->set_name_cache( std::make_unique<FramFsFileNameCacheDynamic>() );

            // Write two files
            if( !write_file( *fix.vfs, "/b/alpha.txt", "alpha" ) ) {
                return false;
            }
            if( !write_file( *fix.vfs, "/b/beta.txt", "beta" ) ) {
                return false;
            }

            // Invalidate the cache
            fix.drive_b->get_name_cache()->invalidate();

            if( fix.drive_b->get_name_cache()->is_valid() ) {
                CPPDEBUG( "test_case_cache_invalidate_fallthrough: cache still valid after invalidate" );
                return false;
            }

            // After invalidation, might_exist must return true for everything
            // (conservative fallback), but flash reads must still be correct.
            if( !fix.drive_b->get_name_cache()->might_exist( "alpha.txt" ) ) {
                CPPDEBUG( "test_case_cache_invalidate_fallthrough: might_exist false after invalidate (should be true)" );
                return false;
            }
            if( !fix.drive_b->get_name_cache()->might_exist( "nonexistent.txt" ) ) {
                CPPDEBUG( "test_case_cache_invalidate_fallthrough: might_exist false for nonexistent after invalidate" );
                return false;
            }

            // Opens still work correctly via flash fallthrough
            auto fh_a = fix.vfs->open( "/b/alpha.txt", std::ios::in );
            if( !fh_a ) {
                CPPDEBUG( "test_case_cache_invalidate_fallthrough: alpha.txt not found on flash" );
                return false;
            }

            auto fh_x = fix.vfs->open( "/b/nonexistent.txt", std::ios::in );
            if( fh_x ) {
                CPPDEBUG( "test_case_cache_invalidate_fallthrough: nonexistent.txt unexpectedly found" );
                return false;
            }

            return true;
        } );
}
